-- Import Winnipeg Snow Removal into the existing active Hidebrandt website-design campaign.
-- Repeated source businesses and existing CRM matches are skipped. Ambiguous records
-- stay in an unassigned Admin review segment. No pre-existing rows are updated.
create temporary table winnipeg_snow_source on commit drop as
select n, name, nullif(phone,'') as phone, nullif(email,'') as email,
       nullif(website,'') as website, nullif(address,'') as address,
       nullif(city,'') as city, nullif(postal,'') as postal,
       nullif(category,'') as category, nullif(search_type,'') as search_type,
       nullif(source_status,'') as source_status,
       regexp_replace(lower(name),'[^a-z0-9]','','g') as name_key,
       right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10) as phone_key,
       case when coalesce(address,'') ~ '^[0-9]' and length(address)>18 then regexp_replace(lower(address),'[^a-z0-9]','','g') else '' end as address_key,
       split_part(regexp_replace(lower(coalesce(website,'')),'^https?://(www\.)?','','g'),'/',1) as website_key
